function applyColourTheme(value,persist=true){
 colourTheme=colourThemes.some(([key])=>key===value)?value:'indigo';
 document.documentElement.dataset.theme=colourTheme;
 if(persist)try{localStorage.setItem('payroll-colour-theme',colourTheme);}catch{}
}
try{applyColourTheme(localStorage.getItem('payroll-colour-theme'),false);}catch{applyColourTheme('indigo',false);}
