  show('Salary payment holds · '+payMonth,'<p>Holds pause payment only. Select a different month in Payroll or Reports to view that month. Administrator, Principal or President can authorize hold/release from the unpaid employee’s Payroll row.</p><div class="actions">'+btn('Download hold register CSV','salary-hold-export',payMonth)+'</div>'+table(['Staff','Net salary','Status','Latest reason','Revision'],rows.map(r=>[esc(r.name),typeof r.net_salary==='number'?money(r.net_salary):esc(r.net_salary),pill(r.status),esc(r.reason),r.revision]))+'<h3>Hold / release history</h3>'+table(['Staff','Decision','Reason','Date','Revision'],events.map(e=>[esc(staff(e.staff_id)?.name||e.staff_id),pill(e.status),esc(e.reason),esc(new Date(e.created_at).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})),e.revision])));return;
